const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n==null?'금액 확인 필요':new Intl.NumberFormat('ko-KR').format(n)+'원';
const labels={cart:'장바구니',pending:'결정 필요',wishlist:'위시리스트',ordered:'주문 완료',shipping:'배송 중',delivered:'배송 완료',installed:'설치 완료',cancelled:'구매 취소',returned:'반품 완료'};
const fieldLabels={status:'구매 상태',quantity:'수량',option:'선택 옵션',orderDate:'주문일',expectedDate:'배송예정일',deliveredDate:'실제 도착일',paidAmount:'상품 결제금액',shippingPaid:'별도 배송비'};
const isActive=p=>!['wishlist','cancelled','returned'].includes(p.status);
const estimate=p=>p.paidAmount??(p.quantity!=null&&p.unitPrice!=null?p.quantity*p.unitPrice:null);
const cats=['전체','조명','욕실','스위치','주방·생활'];
const short=d=>d?new Date(d.length===10?d+'T12:00:00+09:00':d).toLocaleDateString('ko-KR',{month:'long',day:'numeric',timeZone:'Asia/Seoul'}):'미등록';
const full=d=>d?new Date(d).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'미확인';
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});
let data=null,filter='confirmed',category='전체',view='list',query='',sort='curated',month=0;
const group=p=>['ordered','shipping','delivered','installed'].includes(p.status);
const value=(k,v)=>v==null||v===''?'미등록':k==='status'?labels[v]:['paidAmount','shippingPaid'].includes(k)?money(v):esc(v);
const badge=p=>`<span class="badge ${esc(p.status)}">${labels[p.status]||'확인 필요'}</span>`;
const photo=p=>p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)} 대표 사진" loading="lazy">`:`<span class="fallback"><b>⌂</b><span>제품 사진 확인 필요</span></span>`;
const unit=p=>p.quantityLabel?.startsWith('묶음')?'묶음':p.quantityLabel?.startsWith('세트')?'세트':'개';
function card(p){return `<article class="product"><button class="photo" data-item="${esc(p.id)}" aria-label="${esc(p.title)} 상세">${photo(p)}${badge(p)}</button><div class="content"><div class="kicker"><span>${esc(p.category)} · ${esc(p.brand)}</span><span>${esc(p.store)}</span></div><button class="title" data-item="${esc(p.id)}">${esc(p.title)}</button><p class="option">${esc(p.option)}</p><div class="price"><strong>${money(p.unitPrice)}</strong><span>${p.quantity==null?'수량 미정':p.quantity+' '+unit(p)}</span></div><div class="total"><span>${p.paidAmount!=null?'실제 상품 결제':'예상 합계'}</span><b>${p.paidAmount!=null?money(p.paidAmount):p.quotedTotal!=null?money(p.quotedTotal):'—'}</b></div>${p.deliveredDate?`<div class="delivery-label">✓ ${short(p.deliveredDate)} 실제 도착</div>`:p.expectedDate?`<div class="delivery-label">↳ ${short(p.expectedDate)} 도착 예정</div>`:''}<div class="card-link">${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">구매 링크 ↗</a>`:'<span>정확한 모델 미확인</span>'}<button data-item="${esc(p.id)}">기록 보기 ›</button></div></div></article>`;}
function render(){if(!data)return;const ps=data.items,active=ps.filter(isActive),priced=active.filter(p=>estimate(p)!=null),unpriced=active.filter(p=>estimate(p)==null),wishes=ps.filter(p=>p.status==='wishlist'),total=priced.reduce((n,p)=>n+estimate(p),0),counts={all:ps.length,confirmed:active.filter(p=>p.decision==='confirmed').length,wishlist:wishes.length,cart:ps.filter(p=>p.status==='cart').length,ordered:ps.filter(group).length,pending:ps.filter(p=>p.status==='pending').length};$('#total-count').textContent=ps.length;$('#spaces').innerHTML=cats.slice(1).map(c=>`<button data-cat="${c}" class="${category===c?'active':''}">${c}<small>${ps.filter(p=>p.category===c).length}</small></button>`).join('');
 const arrivals=ps.filter(p=>p.expectedDate&&!['delivered','installed','cancelled','returned'].includes(p.status)).sort((a,b)=>a.expectedDate.localeCompare(b.expectedDate));const arr=arrivals[0];
 $('#budget').innerHTML=`<div class="budget-main"><span>구매 예정 상품 합계</span><strong>${money(total)}</strong><p>금액을 계산할 수 있는 ${priced.length}종 합산 · 배송·설치비 별도 · 쿠폰 미적용</p></div><div class="budget-meta"><span>구매 목록 <b>${active.length}종</b></span><span>금액 미산정 <b>${unpriced.length}종</b></span><button data-filter="wishlist">위시리스트 <b>${wishes.length}종 · 합계 제외</b></button></div><details><summary>합계 계산내역</summary>${priced.map(p=>`<div><span>${esc(p.title)} · ${p.quantity??'수량 미확인'} ${unit(p)}</span><b>${money(estimate(p))}</b></div>`).join('')}${unpriced.length?`<p>미산정: ${unpriced.map(p=>esc(p.title)).join(', ')}. 수량 또는 가격 확인 후 합계에 반영돼요.</p>`:''}</details>`;
 $('#stats').innerHTML=[['확정 품목',counts.confirmed+'<small>종</small>','옵션·수량 확인이 남은 제품 포함'],['담아 둔 품목',counts.cart+'<small>종</small>','마지막으로 확인한 기록 기준'],['주문한 품목',counts.ordered+'<small>종</small>','주문·배송·도착·설치 상태'],['다음 도착',arr?short(arr.expectedDate):'날짜를 기다려요',arr?esc(arr.title):'확인된 배송예정일 없음']].map((x,i)=>`<div class="stat"><span>${x[0]}</span><strong class="${i===3?'date':''}">${x[1]}</strong><span>${x[2]}</span></div>`).join('');
 $('#verified-summary').textContent='주문내역 확인 · 오늘의집 '+(data.orderChecks?.ohou?full(data.orderChecks.ohou.at):'미확인')+' / 쿠팡 '+(data.orderChecks?.coupang?full(data.orderChecks.coupang.at):'미확인');$('#check-result').textContent=Object.entries(data.orderChecks??{}).filter(([,c])=>c).map(([k,c])=>(k==='ohou'?'오늘의집':'쿠팡')+': '+c.result).join(' · ');$('#updated').textContent='페이지 갱신 '+full(data.publishedAt);
 $('#status-tabs').innerHTML=[['confirmed','확정 품목'],['cart','장바구니'],['ordered','주문·배송'],['pending','결정 필요'],['wishlist','위시리스트'],['all','전체 기록']].map(([k,l])=>`<button data-filter="${k}" aria-pressed="${filter===k}" class="${filter===k?'active':''}">${l}<span>${counts[k]}</span></button>`).join('');$('#category-tabs').innerHTML=cats.map(c=>`<button data-cat="${c}" aria-pressed="${category===c}" class="${category===c?'active':''}">${c}</button>`).join('');
 const visible=ps.filter(p=>(category==='전체'||category===p.category)&&(!query||[p.title,p.brand,p.label,p.option].join(' ').toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||filter==='confirmed'&&p.decision==='confirmed'&&isActive(p)||filter==='wishlist'&&p.status==='wishlist'||filter==='ordered'&&group(p)||filter==='cart'&&p.status==='cart'||filter==='pending'&&p.status==='pending')).sort((a,b)=>sort==='date'?String(b.updatedAt).localeCompare(String(a.updatedAt)):sort==='price'?(b.quotedTotal??-1)-(a.quotedTotal??-1):a.rank-b.rank);
 $('#visible-count').textContent=visible.length;$('#products').innerHTML=visible.length?visible.map(card).join(''):'<div class="empty">조건에 맞는 제품이 없어요.</div>';
 const paid=ps.filter(p=>p.paidAmount!=null).reduce((s,p)=>s+p.paidAmount+(p.shippingPaid??0),0);$('#price-total').textContent=paid?'등록된 실제 결제금액 '+money(paid):'실제 결제금액 미등록';
 for(const v of ['list','delivery','history'])$('#'+v+'-view').hidden=view!==v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent={list:'구매 목록',delivery:'배송 일정',history:'변경 이력'}[view];if(view==='delivery')renderDelivery();if(view==='history')renderHistory();document.querySelectorAll('img').forEach(im=>im.addEventListener('error',()=>{im.replaceWith(Object.assign(document.createElement('span'),{className:'fallback',textContent:'제품 사진 확인 필요'}))},{once:true}));}
function changes(e){return e.changes.map(c=>`<div class="change">${fieldLabels[c.field]}<del>${value(c.field,c.before)}</del>→ ${value(c.field,c.after)}</div>`).join('');}
function renderHistory(){const events=[...data.history].sort((a,b)=>b.at.localeCompare(a.at));$('#history-view').innerHTML=`<h2>남겨 둔 구매 기록 <small>${events.length}</small></h2><p class="privacy-note">제품 선택·주문·배송 관련 변경을 모았어요. 개인 메모와 주문 식별정보는 공개하지 않아요.</p><div class="timeline">${events.map(e=>`<article class="event"><time>${short(e.at)}</time><div>${e.kind==='check'?`<strong>${esc(e.title)}</strong><p>${esc(e.result)}</p><p>${esc(e.scope)}</p>`:`<button data-item="${esc(e.itemId)}">${esc(e.title)}</button>${e.initial?'<p>초기 제품 선택 기록</p>':changes(e)}`}</div></article>`).join('')}</div>`;}
function renderDelivery(){const now=new Date(today()+'T12:00:00+09:00'),start=new Date(now.getFullYear(),now.getMonth()+month,1),end=new Date(start.getFullYear(),start.getMonth()+1,0).getDate(),count=Math.ceil((start.getDay()+end)/7)*7,date=n=>`${start.getFullYear()}-${String(start.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;let cells='';for(let i=0;i<count;i++){const n=i-start.getDay()+1,d=n>=1&&n<=end?date(n):'';cells+=`<div class="day ${d===today()?'today':''}"><span>${d?n:''}</span>${data.items.filter(p=>d&&(p.expectedDate===d||p.deliveredDate===d)&&!['cancelled','returned'].includes(p.status)).map(p=>`<button class="${p.deliveredDate===d?'arrived':''}" data-item="${esc(p.id)}">${p.deliveredDate===d?'✓':'↳'} ${esc(p.title)}</button>`).join('')}</div>`;}
 const scheduled=data.items.filter(p=>(p.expectedDate||p.deliveredDate)&&!['cancelled','returned'].includes(p.status)).sort((a,b)=>(a.deliveredDate||a.expectedDate).localeCompare(b.deliveredDate||b.expectedDate));const unknown=data.items.filter(p=>['ordered','shipping'].includes(p.status)&&!p.expectedDate);
 $('#delivery-view').innerHTML=`<h2>배송 캘린더</h2><p class="privacy-note">등록한 예정일과 실제 도착일만 표시해요. 미확인 날짜는 비워둡니다.</p><div class="calendar-bar"><button data-month="-1" aria-label="이전 달">‹</button><strong>${start.getFullYear()}년 ${start.getMonth()+1}월</strong><button data-month="1" aria-label="다음 달">›</button></div><div class="calendar">${['일','월','화','수','목','금','토'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div><div class="arrivals">${scheduled.map(p=>`<button class="arrival" data-item="${esc(p.id)}"><small>${short(p.deliveredDate||p.expectedDate)} · ${p.deliveredDate?'실제 도착':'도착 예정'}</small>${esc(p.title)}</button>`).join('')}</div>${!scheduled.length?'<div class="empty">확인된 배송일이 아직 없어요.</div>':''}${unknown.length?`<h3>주문 완료 · 배송일 미확인</h3><div class="arrivals">${unknown.map(p=>`<button class="arrival" data-item="${esc(p.id)}">${esc(p.title)}</button>`).join('')}</div>`:''}`;}
function detail(id){const p=data.items.find(p=>p.id===id);if(!p)return;const es=data.history.filter(e=>e.itemId===id).sort((a,b)=>b.at.localeCompare(a.at));$('#detail-body').innerHTML=`<div class="detail-top">${p.image?photo(p):''}<div><small class="eyebrow">${esc(p.category)} · ${esc(p.brand)}</small><h2 id="detail-title">${esc(p.title)}</h2>${badge(p)}${p.status==='wishlist'?'<p class="wish-note">위시리스트에 보관 · 현재 구매하지 않음 · 구매 합계 제외</p>':''}<p>${esc(p.option)}</p>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">판매페이지 열기 ↗</a>`:''}</div></div><div class="detail-grid">${[['수량',p.quantity==null?'미정':p.quantity+' '+unit(p)],['참고 단가',money(p.unitPrice)],['실제 상품 결제금액',p.paidAmount==null?'미등록':money(p.paidAmount)],['별도 배송비',p.shippingPaid==null?'미등록':money(p.shippingPaid)],['주문일',p.orderDate||'미확인'],['배송예정일',p.expectedDate||'미확인'],['실제 도착일',p.deliveredDate||'미확인'],['참고 가격 기준일',p.sourceDate]].map(([k,v])=>`<div class="detail-field"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="detail-price-note">${esc(p.priceNote)}</p><div class="detail-history"><h3>이 품목의 기록</h3>${es.map(e=>`<p><time>${short(e.at)}</time>${e.initial?'초기 제품 선택 기록':changes(e)}</p>`).join('')}</div>`;$('#detail').showModal();}
async function load(){try{$('#refresh').disabled=true;const r=await fetch('data/purchases.json',{cache:'no-store'});if(!r.ok)throw new Error('기록을 불러오지 못했어요. 잠시 후 새로고침해 주세요.');const d=await r.json();if(!Array.isArray(d.items)||!Array.isArray(d.history))throw new Error('구매 기록 형식 확인이 필요해요.');data=d;$('#error').hidden=true;render();}catch(e){$('#error').textContent=e.message;$('#error').hidden=false;}finally{$('#refresh').disabled=false;}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.cat){category=b.dataset.cat;view='list';render()}if(b.dataset.filter){filter=b.dataset.filter;view='list';render()}if(b.dataset.item)detail(b.dataset.item);if(b.dataset.month){month+=Number(b.dataset.month);renderDelivery()}});$('#search').addEventListener('input',e=>{query=e.target.value;render()});$('#sort').addEventListener('change',e=>{sort=e.target.value;render()});$('#refresh').addEventListener('click',load);$('#detail .close').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});load();
